/* A store's caches are cleared when its products change in the database, whoever changed them: the product editor, the course builder and the OnePage's products tab write products straight from the browser, and a sale changes stock in a function, so no route was told and the website and Explore showed the old price or stock until their minute ran out. A trigger on products, product_variants, inventory_levels, product_collections and product_collection_items posts one small message per store, kind and product, per transaction, to Storelib's /api/internal/invalidate through pg_net, after the write commits; it never slows or stops the write, and does nothing until pg_net is enabled and the address and secret are set in the server only table storelib_cache_invalidation (one row: url, secret; the secret is the same value as the CACHE_INVALIDATE_SECRET environment variable on Vercel). Without pg_net the triggers are skipped with a notice; enable pg_net in Database > Extensions and run this part again. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.storelib_cache_invalidation (id boolean PRIMARY KEY DEFAULT true CHECK (id), url text CHECK (url IS NULL OR (url ~ '^https?://' AND length(url) <= 500)), secret text CHECK (secret IS NULL OR length(secret) BETWEEN 32 AND 200), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.storelib_cache_invalidation ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.storelib_cache_invalidation FROM PUBLIC, anon, authenticated;
INSERT INTO public.storelib_cache_invalidation (id) VALUES (true) ON CONFLICT (id) DO NOTHING;
CREATE OR REPLACE FUNCTION public.storelib_cache_ping() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$ DECLARE r jsonb; v_kind text := TG_ARGV[0]; v_creator uuid; v_product uuid; v_slug text; v_url text; v_secret text; v_key text; BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RETURN NULL; END IF; SELECT c.url, c.secret INTO v_url, v_secret FROM public.storelib_cache_invalidation c WHERE c.id; IF coalesce(v_url, '') !~ '^https?://' OR coalesce(v_secret, '') = '' THEN RETURN NULL; END IF; BEGIN IF TG_OP = 'DELETE' THEN r := to_jsonb(OLD); ELSE r := to_jsonb(NEW); END IF; IF v_kind = 'product' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; v_product := nullif(r ->> 'id', '')::uuid; v_slug := r ->> 'slug'; ELSIF v_kind = 'variant' THEN v_product := nullif(r ->> 'product_id', '')::uuid; SELECT p.creator_id, p.slug INTO v_creator, v_slug FROM public.products p WHERE p.id = v_product; ELSIF v_kind = 'inventory' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; SELECT v.product_id, p.slug INTO v_product, v_slug FROM public.product_variants v JOIN public.products p ON p.id = v.product_id WHERE v.id = nullif(r ->> 'variant_id', '')::uuid; ELSIF v_kind = 'collection' THEN v_creator := nullif(r ->> 'creator_id', '')::uuid; IF v_creator IS NULL THEN SELECT c.creator_id INTO v_creator FROM public.product_collections c WHERE c.id = nullif(r ->> 'collection_id', '')::uuid; END IF; END IF; IF v_creator IS NULL THEN RETURN NULL; END IF; v_key := 'storelib_cache_ping.k' || md5(v_kind || ':' || v_creator::text || ':' || coalesce(v_product::text, '')); IF current_setting(v_key, true) = '1' THEN RETURN NULL; END IF; PERFORM set_config(v_key, '1', true); PERFORM net.http_post(url := v_url, body := jsonb_build_object('creatorId', v_creator, 'kind', v_kind, 'productId', v_product, 'slug', v_slug, 'op', TG_OP), params := '{}'::jsonb, headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_secret), timeout_milliseconds := 3000); EXCEPTION WHEN OTHERS THEN RAISE WARNING 'storelib cache ping skipped: %', SQLERRM; END; RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.storelib_cache_ping() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the products trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.products') IS NULL THEN RAISE NOTICE 'part 179: products is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.products; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.products FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('product'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the product_variants trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.product_variants') IS NULL THEN RAISE NOTICE 'part 179: product_variants is missing (part 78), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.product_variants; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.product_variants FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('variant'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the inventory_levels trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.inventory_levels') IS NULL THEN RAISE NOTICE 'part 179: inventory_levels is missing (part 78), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.inventory_levels; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.inventory_levels FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('inventory'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the product_collections trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.product_collections') IS NULL THEN RAISE NOTICE 'part 179: product_collections is missing (part 95), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.product_collections; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.product_collections FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('collection'); END $do$;
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN RAISE NOTICE 'part 179: pg_net is not enabled, the product_collection_items trigger is skipped. Enable pg_net and run this part again.'; RETURN; END IF; IF to_regclass('public.product_collection_items') IS NULL THEN RAISE NOTICE 'part 179: product_collection_items is missing (part 95), its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS storelib_cache_ping ON public.product_collection_items; CREATE TRIGGER storelib_cache_ping AFTER INSERT OR UPDATE OR DELETE ON public.product_collection_items FOR EACH ROW EXECUTE FUNCTION public.storelib_cache_ping('collection'); END $do$;
notify pgrst, 'reload schema';
